// The runtime every piece NativeShip generates for Activepieces carries.
//
// NativeShip writes each action and trigger as an ordinary Activepieces
// definition -- its props, its name, its description -- whose request is
// data: where every prop goes, where the records are in the answer. This file
// turns that data into HTTP calls. Keeping the logic here, once, rather than
// spelling it out per operation is what keeps the generated files readable
// and the generator from writing TypeScript expressions by string.
//
// Generated by NativeShip. Rebuild from NativeShip rather than editing it: a
// rebuild replaces it.

import { createHmac, timingSafeEqual } from 'node:crypto';
import { DedupeStrategy, pollingHelper } from '@activepieces/pieces-common';
import { api } from './api';

/* eslint-disable @typescript-eslint/no-explicit-any */

export type FieldPlan = {
  key: string;
  label: string;
  in?: 'path' | 'query' | 'header' | 'body';
  name?: string;
  path?: string[];
  // string, integer, number, boolean, date, json, list, lines, dict or file.
  as: string;
  format?: string;
  item?: FieldPlan;
  children?: FieldPlan[];
};

export type RequestPlan = {
  method: string;
  path: string;
  server?: string;
  inputs?: FieldPlan[];
  query?: Record<string, unknown>;
  // raw sends the one body value as it is; multipart sends a form with
  // files.
  body?: string;
  contentType?: string;
  record?: string;
  list?: string;
  pagination?: { style: string; limit: string; size: number; page?: string; cursor?: string; next?: string };
  errors?: Record<string, string>;
  notFound?: 'empty';
  // binary is an answer that is a file, stored in the flow's files.
  binary?: boolean;
};

export type TriggerPlan = {
  id: string;
  changedAt?: string;
  newest?: string;
  // timebased follows the newest field's time; otherwise the trigger
  // remembers the newest record's id.
  timebased?: boolean;
};

// The prop every action and trigger that returns records has: flat,
// table-ready records (Activepieces' guidance) or the API's own JSON.
export const outputFormatKey = 'output_format';

const isEmpty = (value: unknown): boolean =>
  value === undefined || value === null || value === '' || (Array.isArray(value) && value.length === 0);

// get reads a dotted path ("data.items") from a value; an empty path is the
// value itself.
function get(value: any, path?: string): any {
  if (!path) return value;
  for (const part of path.split('.')) {
    if (value === null || value === undefined) return undefined;
    value = value[part];
  }
  return value;
}

function setPath(target: any, path: string[], value: unknown): void {
  let cursor = target;
  path.slice(0, -1).forEach((part) => {
    if (cursor[part] === null || typeof cursor[part] !== 'object') cursor[part] = {};
    cursor = cursor[part];
  });
  cursor[path[path.length - 1]] = value;
}

// connection flattens what Activepieces hands a piece for a connection --
// a secret text, a username and password, custom props or an OAuth token,
// each in its own shape, or the plain values validate receives -- into one
// map of the connection's fields, the names api.auth's templates use.
export function connection(auth: unknown): Record<string, unknown> {
  if (auth === null || auth === undefined) return {};
  if (typeof auth === 'string') return api.auth.secretField ? { [api.auth.secretField]: auth } : {};
  const value = auth as any;
  if (value.secret_text !== undefined) {
    return api.auth.secretField ? { [api.auth.secretField]: value.secret_text } : {};
  }
  if (value.access_token !== undefined) return Object.assign({}, value.props, { access_token: value.access_token });
  if (value.props && typeof value.props === 'object') return Object.assign({}, value.props);
  return Object.assign({}, value);
}

// fill replaces {{field}} in a template with the connection's own fields.
function fill(template: string, data: Record<string, unknown>): string {
  let missing = false;
  const value = template.replace(/\{\{([^{}]+)\}\}/g, (_, name: string) => {
    const field = data[name.trim()];
    if (isEmpty(field)) missing = true;
    return isEmpty(field) ? '' : String(field);
  });
  return missing ? '' : value;
}

// A connection's own part of an address -- a sub-domain, a region -- is
// letters, digits, dots, dashes and underscores; a whole address is HTTPS.
// Anything else could send the connection's credentials somewhere the
// person did not mean.
const addressPart = /^[A-Za-z0-9](?:[A-Za-z0-9._-]*[A-Za-z0-9])?$/;
const wholeAddress = /^https:\/\/[A-Za-z0-9.-]+(?::\d+)?(?:\/[^\s?#]*)?$/;

function variableValue(variable: { label?: string; url?: boolean }, value: unknown): string {
  const text = String(value).trim();
  if (variable.url) {
    if (!wholeAddress.test(text)) {
      throw new Error(`${variable.label || 'The server URL'} must be an HTTPS address, such as https://api.example.com.`);
    }
    return text.replace(/\/+$/, '');
  }
  if (!addressPart.test(text)) {
    throw new Error(`${variable.label || 'The server setting'} may hold only letters, digits, dots and dashes, not "${text.slice(0, 60)}".`);
  }
  return text;
}

// serverURL is the API's address for a connection: the server it chose, with
// the variables it set, or the specification's defaults.
export function serverURL(auth: unknown, pinned?: string): string {
  const servers = api.servers;
  const data = connection(auth);
  let id = pinned || servers.default;
  if (!pinned && servers.choice && !isEmpty(data[servers.choice])) id = String(data[servers.choice]);
  const server = servers.list.find((entry) => entry.id === id) || servers.list.find((entry) => entry.id === servers.default)!;
  const url = server.url.replace(/\{([^{}]+)\}/g, (match: string, name: string) => {
    const variable = ((server as any).variables || {})[name];
    if (!variable) return match;
    const value = variable.field ? data[variable.field] : undefined;
    return isEmpty(value) ? variable.default : variableValue(variable, value);
  });
  return url.replace(/\/+$/, '');
}

// credentials are the headers and query values a connection signs a request
// with.
export function credentials(auth: unknown): { headers: Record<string, string>; query: Record<string, string> } {
  const data = connection(auth);
  const headers: Record<string, string> = {};
  const query: Record<string, string> = {};
  if (api.auth.type === 'oauth2' && !isEmpty(data.access_token)) headers.Authorization = `Bearer ${data.access_token}`;
  if (api.auth.type === 'basic' && !isEmpty(data.username)) {
    headers.Authorization = 'Basic ' + Buffer.from(`${data.username}:${data.password ?? ''}`).toString('base64');
  }
  for (const injection of api.auth.inject || []) {
    const value = fill(injection.value, data);
    if (isEmpty(value)) continue;
    if (injection.in === 'query') query[injection.name] = value;
    else headers[injection.name] = value;
  }
  return { headers, query };
}

function toDate(value: unknown): string {
  const text = String(value).trim();
  if (/^\d{4}-\d{2}-\d{2}$/.test(text)) return text;
  const parsed = new Date(text);
  return Number.isNaN(parsed.getTime()) ? text : parsed.toISOString().slice(0, 10);
}

// convert turns what a prop holds -- often text, since mapped values arrive
// as strings -- into the type the API takes.
function convert(value: any, field: FieldPlan): any {
  switch (field.as) {
    case 'integer':
    case 'number': {
      if (typeof value === 'number') return value;
      const number = Number(String(value).trim());
      if (Number.isNaN(number)) throw new Error(`${field.label} must be a number, not "${value}".`);
      return number;
    }
    case 'boolean':
      return value === true || /^(true|yes|1)$/i.test(String(value).trim());
    case 'date':
      return toDate(value);
    case 'json':
      if (typeof value !== 'string') return value;
      try {
        return JSON.parse(value);
      } catch (error) {
        throw new Error(`${field.label} must be JSON: ${(error as Error).message}`);
      }
    case 'list': {
      const items: any[] = Array.isArray(value) ? value : String(value).split(',').map((item) => item.trim());
      return items.filter((item) => !isEmpty(item)).map((item) => convert(item, field.item || { key: field.key, as: 'string', label: field.label }));
    }
    case 'lines':
      return (Array.isArray(value) ? value : [value]).map((line: any) => {
        const record = {};
        for (const child of field.children || []) {
          const childValue = (line || {})[child.key];
          if (!isEmpty(childValue)) setPath(record, child.path || [child.key], convert(childValue, child));
        }
        return record;
      });
    case 'dict':
      return typeof value === 'object' ? value : convert(value, { key: field.key, as: 'json', label: field.label });
    case 'file':
      // Activepieces hands a File prop over as an ApFile: its name and bytes.
      if (value && typeof value === 'object' && value.data !== undefined) return value;
      throw new Error(`${field.label} must be a file.`);
    default:
      return typeof value === 'string' ? value : String(value);
  }
}

function addQuery(query: string[], name: string, value: any, format?: string): void {
  const key = encodeURIComponent(name);
  const encode = (item: any) => encodeURIComponent(typeof item === 'object' ? JSON.stringify(item) : String(item));
  if (Array.isArray(value)) {
    switch (format) {
      case 'comma':
        query.push(`${key}=${value.map(encode).join(',')}`);
        return;
      case 'repeat':
        value.forEach((item) => query.push(`${key}=${encode(item)}`));
        return;
      case 'brackets':
        value.forEach((item) => query.push(`${key}%5B%5D=${encode(item)}`));
        return;
      default:
        value.forEach((item, index) => query.push(`${key}%5B${index}%5D=${encode(item)}`));
        return;
    }
  }
  if (value !== null && typeof value === 'object') {
    Object.entries(value).forEach(([property, item]) => query.push(`${key}%5B${encodeURIComponent(property)}%5D=${encode(item)}`));
    return;
  }
  query.push(`${key}=${encode(value)}`);
}

type Built = { url: string; init: { method: string; headers: Record<string, string>; body?: any } };

// A file's bytes as a Blob, which FormData and fetch both take.
function blob(file: any): Blob {
  return new Blob([new Uint8Array(file.data)]);
}

// buildRequest makes the HTTP request a plan describes from a step's props.
function buildRequest(auth: unknown, plan: RequestPlan, inputs: Record<string, unknown>, extraQuery?: Record<string, unknown>): Built {
  let path = plan.path;
  const query: string[] = [];
  const signed = credentials(auth);
  const headers: Record<string, string> = Object.assign({ Accept: 'application/json' }, signed.headers);
  let body: any;
  const files: { path: string[]; file: any }[] = [];
  for (const field of plan.inputs || []) {
    const raw = inputs[field.key];
    if (isEmpty(raw) || (field.as === 'dict' && typeof raw === 'object' && Object.keys(raw as object).length === 0)) {
      if (field.in === 'path') throw new Error(`${field.label} is required.`);
      continue;
    }
    const value = convert(raw, field);
    switch (field.in) {
      case 'path':
        path = path.split(`{${field.name}}`).join(encodeURIComponent(String(value)));
        break;
      case 'query':
        addQuery(query, field.name!, value, field.format);
        break;
      case 'header':
        headers[field.name!] = String(value);
        break;
      default:
        if (plan.body === 'raw') {
          body = value;
        } else if (field.as === 'file') {
          files.push({ path: field.path || [field.key], file: value });
        } else {
          body = body || {};
          setPath(body, field.path || [field.key], value);
        }
    }
  }
  for (const [name, value] of Object.entries(Object.assign({}, plan.query, extraQuery))) {
    if (!isEmpty(value)) addQuery(query, name, value, 'repeat');
  }
  for (const [name, value] of Object.entries(signed.query)) addQuery(query, name, value);
  const built: Built = {
    url: serverURL(auth, plan.server) + path + (query.length ? `?${query.join('&')}` : ''),
    init: { method: plan.method, headers },
  };
  if (plan.body === 'multipart') {
    // fetch sets the multipart boundary itself, so no Content-Type here.
    const form = new FormData();
    for (const [name, value] of Object.entries(body || {})) {
      form.append(name, typeof value === 'object' ? JSON.stringify(value) : String(value));
    }
    for (const entry of files) form.append(entry.path.join('.'), blob(entry.file), entry.file.filename || 'file');
    built.init.body = form;
    return built;
  }
  if (body !== undefined) {
    const contentType = plan.contentType || 'application/json';
    headers['Content-Type'] = contentType;
    if (body && typeof body === 'object' && body.data !== undefined && body.filename !== undefined) {
      built.init.body = blob(body);
    } else if (/json/i.test(contentType)) {
      built.init.body = JSON.stringify(body);
    } else if (/x-www-form-urlencoded/i.test(contentType)) {
      const form: string[] = [];
      Object.entries(body).forEach(([name, value]) => addQuery(form, name, value, 'brackets'));
      built.init.body = form.join('&');
    } else {
      built.init.body = typeof body === 'string' ? body : JSON.stringify(body);
    }
  }
  return built;
}

function parse(text: string): any {
  if (text.trim() === '') return null;
  try {
    return JSON.parse(text);
  } catch {
    return { content: text };
  }
}

// apiMessage is the reason an API gives for refusing a request, in the
// places APIs usually put it.
function apiMessage(data: any): string {
  if (!data || typeof data !== 'object') return '';
  const first = Array.isArray(data.errors) ? data.errors[0] : undefined;
  const candidates = [
    data.message,
    data.error_description,
    typeof data.error === 'string' ? data.error : get(data, 'error.message'),
    data.detail,
    data.title,
    typeof first === 'string' ? first : get(first, 'message'),
    data.content,
  ];
  const found = candidates.find((value) => typeof value === 'string' && value.trim() !== '');
  return found ? found.trim().slice(0, 500) : '';
}

async function send(auth: unknown, plan: RequestPlan, inputs: Record<string, unknown>, extraQuery?: Record<string, unknown>) {
  const request = buildRequest(auth, plan, inputs, extraQuery);
  const response = await fetch(request.url, request.init);
  if (response.ok) return response;
  const text = await response.text();
  if (response.status === 404 && plan.notFound === 'empty') return undefined;
  const reason = apiMessage(parse(text)) || (plan.errors || {})[String(response.status)] || `HTTP ${response.status}`;
  if (response.status === 401) throw new Error(`${api.title} did not accept the connection's credentials: ${reason}`);
  if (response.status === 429) throw new Error(`${api.title} is limiting requests: ${reason}`);
  throw new Error(`${api.title} answered ${response.status}: ${reason}`);
}

export async function call(auth: unknown, plan: RequestPlan, inputs: Record<string, unknown>, extraQuery?: Record<string, unknown>): Promise<any> {
  const response = await send(auth, plan, inputs, extraQuery);
  return response ? parse(await response.text()) : undefined;
}

// records are the list in an answer, wherever the plan says it is.
function records(data: any, plan: RequestPlan): any[] {
  const list = get(data, plan.list);
  if (Array.isArray(list)) return list.filter((item) => item !== null && typeof item === 'object');
  return [];
}

function record(data: any, plan: RequestPlan): any {
  if (data === null || data === undefined) return null;
  const value = get(data, plan.record);
  return value === undefined ? data : value;
}

// flatten makes a record table-ready, as Activepieces asks of a piece's
// output: nested objects become prefixed keys (user.name -> user_name),
// lists of plain values are joined, and lists of records are kept as JSON
// text, so every value maps onto a spreadsheet column.
export function flatten(value: Record<string, any>, prefix = ''): Record<string, unknown> {
  const result: Record<string, unknown> = {};
  for (const [key, item] of Object.entries(value)) {
    const name = prefix ? `${prefix}_${key}` : key;
    if (item === null || item === undefined) {
      result[name] = null;
    } else if (Array.isArray(item)) {
      result[name] = item.map((entry) => (entry !== null && typeof entry === 'object' ? JSON.stringify(entry) : String(entry))).join(', ');
    } else if (typeof item === 'object') {
      Object.assign(result, flatten(item, name));
    } else {
      result[name] = item;
    }
  }
  return result;
}

// table flattens a list of records with the same keys on every one -- a key
// a record lacks is null -- so the columns line up.
function table(items: any[]): Record<string, unknown>[] {
  const flat = items.map((item) => flatten(item));
  const keys = new Set<string>();
  flat.forEach((item) => Object.keys(item).forEach((key) => keys.add(key)));
  return flat.map((item) => {
    const row: Record<string, unknown> = {};
    keys.forEach((key) => (row[key] = key in item ? item[key] : null));
    return row;
  });
}

// isFile is an answer that is not data: anything but JSON, text, XML and
// form encoding, or an answer naming itself an attachment.
function isFile(response: Response): boolean {
  if (/^\s*attachment/i.test(response.headers.get('content-disposition') || '')) return true;
  const type = (response.headers.get('content-type') || '').split(';')[0].trim().toLowerCase();
  if (type === '') return false;
  return !(type.startsWith('text/') || /[/+]json$/.test(type) || /[/+]xml$/.test(type) || type === 'application/x-www-form-urlencoded');
}

const raw = (propsValue: Record<string, unknown> | undefined) => (propsValue || {})[outputFormatKey] === 'raw';

// run is an action: one request, answering with the record it read or
// affected, the records a list holds, or the file it downloaded. An empty
// answer -- a delete's 204 -- answers with the record's path values, so a
// later step can still map which record it was.
export async function run(
  context: { auth: unknown; propsValue: Record<string, unknown>; files?: any },
  plan: RequestPlan,
): Promise<unknown> {
  const response = await send(context.auth, plan, context.propsValue);
  // A file is what the specification says is one, or what the API answers
  // as one: most specifications say "application/pdf" and nothing more, so
  // the answer's own type decides, and a PDF is never read as text.
  if (plan.binary || (response && plan.list === undefined && isFile(response))) {
    if (!response) return null;
    const data = Buffer.from(await response.arrayBuffer());
    const disposition = response.headers.get('content-disposition') || '';
    const named = /filename\*?=(?:UTF-8'')?"?([^";]+)"?/i.exec(disposition);
    const fileName = named ? decodeURIComponent(named[1]) : `${plan.path.split('/').filter(Boolean).pop() || 'download'}`;
    const file = await context.files.write({ fileName, data });
    return { file, file_name: fileName, size: data.length, content_type: response.headers.get('content-type') };
  }
  const data = response ? parse(await response.text()) : undefined;
  if (plan.list !== undefined) {
    const list = records(data, plan);
    return raw(context.propsValue) ? list : table(list);
  }
  const value = record(data, plan);
  if (value === null || value === undefined) {
    const affected: Record<string, unknown> = {};
    for (const field of plan.inputs || []) {
      if (field.in === 'path' && !isEmpty(context.propsValue[field.key])) affected[field.name!] = context.propsValue[field.key];
    }
    return Object.assign(affected, { success: true });
  }
  if (raw(context.propsValue) || typeof value !== 'object' || Array.isArray(value)) return value;
  return flatten(value);
}

// choices lists what a dropdown offers: each record of a list, by the value
// it sends and a label naming it -- with a second field telling records with
// the same name apart, "Jane Doe (jane@example.com)".
export function choices(plan: RequestPlan, value: string, label: string, detail?: string, noun = 'record') {
  return async ({ auth }: { auth?: unknown }) => {
    // A piece that signs in has nothing to list until a connection is
    // chosen; one that does not lists at once.
    if (api.auth.type !== 'none' && (auth === undefined || auth === null)) {
      return { disabled: true, placeholder: 'Please connect your account first', options: [] };
    }
    try {
      const query = plan.pagination && plan.pagination.limit ? { [plan.pagination.limit]: plan.pagination.size } : undefined;
      const options = records(await call(auth, plan, {}, query), plan)
        .map((item) => {
          const name = get(item, label);
          const extra = detail ? get(item, detail) : undefined;
          const text = isEmpty(name) ? String(get(item, value)) : String(name);
          return { value: get(item, value), label: isEmpty(extra) || extra === name ? text : `${text} (${extra})` };
        })
        .filter((option) => !isEmpty(option.value));
      if (options.length === 0) return { disabled: false, placeholder: `No ${noun} found.`, options };
      return { disabled: false, options };
    } catch (error) {
      return { disabled: true, placeholder: `Failed to load ${noun}. Check your connection. (${(error as Error).message.slice(0, 120)})`, options: [] };
    }
  };
}

// newestFirst orders records by the field a trigger follows, newest first:
// by time where the values are dates, by number where they are numbers. A
// record without one goes last.
function newestFirst(items: any[], field?: string): any[] {
  if (!field) return items;
  const rank = (item: any): number => {
    const value = get(item, field);
    if (isEmpty(value)) return -Infinity;
    if (typeof value === 'number') return value;
    const time = Date.parse(String(value));
    if (!Number.isNaN(time)) return time;
    const number = Number(value);
    return Number.isNaN(number) ? -Infinity : number;
  };
  return items
    .map((item, index) => ({ item, index, rank: rank(item) }))
    .sort((a, b) => b.rank - a.rank || a.index - b.index)
    .map((entry) => entry.item);
}

// poll is a polling trigger's four hooks, on Activepieces' polling helper:
// every few minutes the list is fetched newest first, and the records newer
// than the last seen -- by time, or by id where records carry no usable time
// -- start a flow each. The helper is handed the whole context, as
// Activepieces asks: it reads more than the store (a republished flow keeps
// its place by isRepublish).
export function poll(plan: RequestPlan, trigger: TriggerPlan) {
  const fetchRecords = async (auth: unknown, propsValue: Record<string, unknown>) => {
    const query = plan.pagination && plan.pagination.limit ? { [plan.pagination.limit]: plan.pagination.size } : undefined;
    return newestFirst(records(await call(auth, plan, propsValue || {}, query), plan), trigger.newest);
  };
  const shape = (item: any, propsValue: Record<string, unknown>) => (raw(propsValue) ? item : flatten(item));
  const polling: any = trigger.timebased
    ? {
        strategy: DedupeStrategy.TIMEBASED,
        items: async ({ auth, propsValue }: any) =>
          (await fetchRecords(auth, propsValue))
            .map((item) => ({ epochMilliSeconds: Date.parse(String(get(item, trigger.newest))), data: shape(item, propsValue) }))
            .filter((item) => !Number.isNaN(item.epochMilliSeconds)),
      }
    : {
        strategy: DedupeStrategy.LAST_ITEM,
        items: async ({ auth, propsValue }: any) =>
          (await fetchRecords(auth, propsValue))
            .map((item) => ({ id: get(item, trigger.id), data: shape(item, propsValue) }))
            .filter((item) => !isEmpty(item.id)),
      };
  return {
    onEnable: async (context: any) => {
      await pollingHelper.onEnable(polling, context);
    },
    onDisable: async (context: any) => {
      await pollingHelper.onDisable(polling, context);
    },
    run: async (context: any) => pollingHelper.poll(polling, context),
    test: async (context: any) => pollingHelper.test(polling, context),
  };
}

export type HookPlan = {
  subscribe: RequestPlan;
  unsubscribe: RequestPlan;
  targetKey: string;
  idKey: string;
  subscriptionId: string;
  list?: RequestPlan;
  // The API's own checks on what it sends: the query parameter it
  // challenges a new URL with, the header carrying each event's HMAC-SHA256
  // signature and the connection field holding its secret, the event type
  // the trigger is for, and how many recent events to remember to drop
  // repeats.
  challenge?: string;
  signatureHeader?: string;
  secretField?: string;
  secretProp?: string;
  eventType?: string;
  dedupeKey?: string;
  dedupeWindow?: number;
};

// The store keys a webhook trigger keeps its state under.
const subscriptionKey = 'nativeship_subscription';
const seenKey = 'nativeship_seen_events';

// hook is a webhook trigger's hooks: when a flow is published the API is
// asked to send events to the flow's webhook URL, and when it is unpublished
// to stop. An event is checked the way the API signs it, filtered to the
// trigger's event type, and dropped when it repeats one recently seen. A
// test lists records the API already has, so a person need not wait for an
// event.
export function hook(plan: HookPlan) {
  const verify = (context: any) => {
    if (!plan.signatureHeader) return;
    const secret = plan.secretProp
      ? (context.propsValue || {})[plan.secretProp]
      : connection(context.auth)[plan.secretField || ''];
    if (typeof secret !== 'string' || secret === '') throw new Error('The webhook signing secret is missing.');
    const headers = context.payload.headers || {};
    const provided = String(headers[plan.signatureHeader.toLowerCase()] ?? headers[plan.signatureHeader] ?? '');
    const signed = typeof context.payload.rawBody === 'string' ? context.payload.rawBody : JSON.stringify(context.payload.body);
    const expected = 'sha256=' + createHmac('sha256', secret).update(signed).digest('hex');
    if (provided.length !== expected.length || !timingSafeEqual(Buffer.from(provided), Buffer.from(expected))) {
      throw new Error('The webhook signature is invalid.');
    }
  };
  return {
    onEnable: async (context: any) => {
      const inputs = Object.assign({}, context.propsValue, { [plan.targetKey]: context.webhookUrl });
      const data = await call(context.auth, plan.subscribe, inputs);
      const id = get(data, plan.subscriptionId);
      if (isEmpty(id)) throw new Error(`${api.title} did not say which subscription it made.`);
      await context.store.put(subscriptionKey, String(id));
    },
    onDisable: async (context: any) => {
      const id = await context.store.get(subscriptionKey);
      if (isEmpty(id)) return;
      await call(context.auth, plan.unsubscribe, Object.assign({}, context.propsValue, { [plan.idKey]: id }));
      await context.store.delete(subscriptionKey);
    },
    onHandshake: async (context: any) => ({
      status: 200,
      body: String(((context.payload && context.payload.queryParams) || {})[plan.challenge || ''] ?? ''),
      headers: { 'Content-Type': 'text/plain' },
    }),
    run: async (context: any) => {
      verify(context);
      const body = context.payload && context.payload.body;
      let items: any[] = (Array.isArray(body) ? body : [body]).filter((item: unknown) => item !== null && typeof item === 'object');
      if (plan.eventType) {
        items = items.filter((item) => String(get(item, 'event.type') ?? get(item, 'type') ?? '') === plan.eventType);
      }
      if (plan.dedupeKey) {
        const seen: string[] = (await context.store.get(seenKey)) || [];
        const fresh: any[] = [];
        for (const item of items) {
          const key = get(item, plan.dedupeKey);
          if (isEmpty(key) || seen.includes(String(key))) continue;
          seen.push(String(key));
          fresh.push(item);
        }
        items = fresh;
        await context.store.put(seenKey, seen.slice(-(plan.dedupeWindow || 100)));
      }
      return raw(context.propsValue) ? items : items.map((item) => flatten(item));
    },
    test: async (context: any) => {
      if (!plan.list) return [];
      const items = records(await call(context.auth, plan.list, {}), plan.list).slice(0, 5);
      return raw(context.propsValue) ? items : items.map((item) => flatten(item));
    },
  };
}

// validate checks a connection with one request the API answers only when
// its credentials are good.
export function validate(plan: RequestPlan) {
  return async ({ auth }: { auth: unknown }): Promise<{ valid: true } | { valid: false; error: string }> => {
    try {
      await call(auth, plan, {});
      return { valid: true };
    } catch (error) {
      return { valid: false, error: (error as Error).message };
    }
  };
}

// identify names a connection by the account it signs in as -- its email,
// else its name -- read from the API's own "who am I" endpoint, so a person
// with two accounts can tell their connections apart. Best effort: anything
// that goes wrong names nothing rather than refusing the connection.
export function identify(plan: RequestPlan, fields: string[]) {
  return async ({ auth }: { auth: unknown }): Promise<string | undefined> => {
    try {
      const found = record(await call(auth, plan, {}), plan);
      const name = fields.map((field) => get(found, field)).find((value) => !isEmpty(value));
      return name === undefined ? undefined : String(name);
    } catch {
      return undefined;
    }
  };
}
